          comments(first: 20) {
            nodes {
              databaseId
              author { login }
              body
            }
          }
        }
      }
    }
  }
}' > <repo>/.tmp/pr534-threads.json 2>&1
wc -l <repo>/.tmp/pr534-threads.json

